jQuery(document).ready(function ($) {
if ($("meta[name=toTop]").attr("content") == "true") {
$("返回顶部
").appendTo('body');
$("#toTop").css({
// width: '50px',
// height: '50px',
bottom: '10px',
right: '15px',
position: 'fixed',
cursor: 'pointer',
zIndex: '2',
});
if ($(this).scrollTop() == 0) {
$("#toTop").hide();
}
$(window).scroll(function (event) {
/* Act on the event */
if ($(this).scrollTop() == 0) {
$("#toTop").hide();
}
if ($(this).scrollTop() != 0) {
$("#toTop").show();
}
});
$("#toTop").click(function (event) {
/* Act on the event */
$("html,body").animate({
scrollTop: "0px"
},
300
)
});
}
});
